// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

/** A PHC inspector's read-only guest login (msds/inspectors.py). */
export interface InspectorAccountOut {
  inspector_account_id: number;
  user_id: number;
  username: string;
  inspector_name: string;
  designation: string | null;
  organization: string;
  reference: string | null;
  valid_from: string;
  /** The last day of access, inclusive; the login stops at midnight after it */
  valid_until: string;
  note: string | null;
  is_active: boolean;
  expires_at: string;
  state: "Active" | "NotYetValid" | "Expired" | "Revoked";
  created_by: number;
  created_by_name: string;
  created_at: string;
  revoked_at: string | null;
  revoked_by: number | null;
  revoked_by_name: string | null;
  revoke_reason: string | null;
  last_login_at: string | null;
  /** Downloads that named patients (phi_access_log) */
  documents_read: number;
  row_version: number;
}

/** A read-only guest login for one PHC inspector, for the days of the inspection (msds/inspectors.py). */
export interface InspectorAccountIn {
  inspector_name: string;
  designation?: string | null;
  /** Default: Punjab Healthcare Commission */
  organization?: string | null;
  /** The PHC's letter or notice of the inspection */
  reference?: string | null;
  /** Default: today */
  valid_from?: string | null;
  /** The last day of access (inclusive); at most inspector_access_max_days after valid_from */
  valid_until: string;
  note?: string | null;
}

export interface InspectorAccountCreatedOut {
  inspector_account_id: number;
  user_id: number;
  username: string;
  inspector_name: string;
  designation: string | null;
  organization: string;
  reference: string | null;
  valid_from: string;
  /** The last day of access, inclusive; the login stops at midnight after it */
  valid_until: string;
  note: string | null;
  is_active: boolean;
  expires_at: string;
  state: "Active" | "NotYetValid" | "Expired" | "Revoked";
  created_by: number;
  created_by_name: string;
  created_at: string;
  revoked_at: string | null;
  revoked_by: number | null;
  revoked_by_name: string | null;
  revoke_reason: string | null;
  last_login_at: string | null;
  /** Downloads that named patients (phi_access_log) */
  documents_read: number;
  row_version: number;
  /** Shown ONCE: hand it to the inspector; only its hash is stored */
  temporary_password: string;
}

export interface InspectorRevokeIn {
  reason: string;
}

export interface InspectorActivityOut {
  account: InspectorAccountOut;
  logins: InspectorLoginOut[];
  documents_read: InspectorReadOut[];
}

export interface InspectorLoginOut {
  at: string;
  ip: string | null;
  is_success: boolean;
  failure_reason: string | null;
}

export interface InspectorReadOut {
  at: string;
  /** e.g. msds_document.incident_register, cpsa_document.er_register */
  resource: string;
  resource_id: string | null;
  ip: string | null;
}

/** The PHC inspectors' logins (the current ones; include_closed for the history) — GET /api/v1/msds/inspector-accounts (who may call: holders of msds.inspector.manage). */
export function listInspectors(query?: { include_closed?: boolean }): Promise<InspectorAccountOut[]> {
  return api<InspectorAccountOut[]>("GET", withQuery(`/msds/inspector-accounts`, query), undefined);
}

/** Give a PHC inspector a read-only login for the days of the inspection (password shown ONCE) — POST /api/v1/msds/inspector-accounts (who may call: holders of msds.inspector.manage). */
export function createInspector(body: InspectorAccountIn): Promise<InspectorAccountCreatedOut> {
  return api<InspectorAccountCreatedOut>("POST", `/msds/inspector-accounts`, body);
}

/** End an inspector's access now — POST /api/v1/msds/inspector-accounts/{inspector_account_id}/revoke (who may call: holders of msds.inspector.manage). */
export function revokeInspector(inspector_account_id: number, body: InspectorRevokeIn): Promise<InspectorAccountOut> {
  return api<InspectorAccountOut>("POST", `/msds/inspector-accounts/${inspector_account_id}/revoke`, body, { idempotent: true });
}

/** What an inspector did: logins and the documents they read — GET /api/v1/msds/inspector-accounts/{inspector_account_id}/activity (who may call: holders of msds.inspector.manage). */
export function inspectorActivity(inspector_account_id: number): Promise<InspectorActivityOut> {
  return api<InspectorActivityOut>("GET", `/msds/inspector-accounts/${inspector_account_id}/activity`, undefined);
}
